primef = [[] for i in range(10 ** 6 + 1)]
for val in range(2, 10 ** 6):
	if primef[val] != []:
		continue
	else:
		for i in range(val, 10 ** 6 + 1, val):
			primef[i].append(val)

def min_possible(a):
	if len(a) == k:
		return sum(a)
	value = 10 ** 8
	for i in range(len(a) - 1):
		for j in range(i + 1, len(a)):
			x = a[:]
			temp = a[i] * a[j]
			x.remove(a[i])
			x.remove(a[j])
			x.append(temp)
			value = min(value, min_possible(x))
	return value

def answer(x, k):
	(s, val) = (0, x)
	all_ = []
	for i in primef[val]:
		p = 0
		while x % i == 0:
			x //= i
			p += 1
		all_.append(i ** p)
	if k - len(primef[val]) >= 0:
		return min(sum(all_) + (k - len(primef[val])), val + (k - 1))
	else:
		return min_possible(all_)
